继承A合约中的方法，可以直接调用。
contract A {
    uint public x;
    function setValue(uint _x) public {
        x = _x;
    }
}

contract B is A {
    function modify(uint _y) public {
        setValue(_y); //可以直接调用A合约中的方法
    }
}

